SELECT * FROM (SELECT CASE WHEN rating >= 3.8 THEN 'high' WHEN rating >= 2.3 THEN 'mid' ELSE 'low' END AS rating_bucket, SUM(CASE WHEN city = 'New York' THEN 1 ELSE 0 END) AS new_york_count, SUM(CASE WHEN country = 'US' THEN rating ELSE 0 END) AS us_rating FROM suppliers GROUP BY CASE WHEN rating >= 3.8 THEN 'high' WHEN rating >= 2.3 THEN 'mid' ELSE 'low' END) AS s WHERE us_rating < 67;
